import os,json,html
from fastapi import FastAPI,Request,Header
from fastapi.responses import HTMLResponse,JSONResponse
from shared.http import get_json,post_json
from portal.portal_integrations import build_navigation, render_navigation_html
from portal.portal_read_models import read_portal_snapshot
from portal.portal_command_auth import require_demo_operator
from portal.noc_runtime import router as noc_runtime_router
from portal.noc_correlation import router as noc_correlation_router
from portal.noc_demo_rag import router as noc_demo_rag_router
from portal.acme_impact_read_model import router as acme_impact_router
app=FastAPI(title='ACME AioOps Command Center',version='2.0.0')
app.include_router(noc_runtime_router)
app.include_router(noc_correlation_router)
app.include_router(noc_demo_rag_router)
app.include_router(acme_impact_router)
CORE=os.getenv('CORE_URL','http://aiops2-core:810');COPILOT=os.getenv('COPILOT_URL','http://aiops2-copilot:814');TWIN=os.getenv('TWIN_URL','http://aiops2-twin:811')
@app.get('/health')
def health():return {'status':'ok','component':'portal','external_port':os.getenv('AIOPS_PORTAL_HOST_PORT','17777'),'internal_port':777}
@app.get('/api/portal/bootstrap')
def bootstrap():return JSONResponse(read_portal_snapshot(get_json,CORE,TWIN),headers={'Cache-Control':'no-store'})
@app.get('/api/portal/components')
def components():
    return JSONResponse(build_navigation(),headers={'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'})
@app.post('/api/copilot')
def copilot(q:dict):return post_json(COPILOT,'/api/copilot/query',q)
@app.post('/api/demo')
def demo(authorization: str | None = Header(default=None)):
    require_demo_operator(authorization)
    iid=post_json(CORE,'/api/incidents',{'external_id':'DEMO-GOLDEN-PAYMENT','title':'Payment latency following FC fabric degradation','severity':'P1','service_id':'ACME-SVC-PAYMENTS','source':'portal-demo','synthetic':True,'payload':{'seed':20261018}})['incident_id']
    run=post_json(CORE,'/api/runs',{'mode':'DEMO','scenario_id':'SCN-GOLDEN-PAYMENT-P1','incident_id':iid,'idempotency_key':'DEMO-GOLDEN-PAYMENT'})
    return post_json(CORE,f"/api/runs/{run['run_id']}/execute")
@app.get('/',response_class=HTMLResponse)
def home():
    snapshot=read_portal_snapshot(get_json,CORE,TWIN)
    d=snapshot['dashboard'] or {};runs=(snapshot['runs'] or {}).get('items',[]);t=snapshot['twin'] or {'state':'UNKNOWN'}
    read_model_status=html.escape(json.dumps(snapshot['states'],sort_keys=True))
    integration_html=render_navigation_html(build_navigation())
    cards=[('Open P1',d.get('open_p1','UNKNOWN')),('Incidents',d.get('open_incidents','UNKNOWN')),('Running',d.get('running','UNKNOWN')),('Blocked',d.get('blocked','UNKNOWN')),('Twin nodes',d.get('twin_nodes','UNKNOWN')),('Degraded',d.get('degraded_nodes','UNKNOWN'))]
    cards_html=''.join(f'<div class="card"><span>{html.escape(str(k))}</span><strong>{v}</strong></div>' for k,v in cards)
    rows=''.join(f'<tr><td><code>{html.escape(str(r["run_id"]))}</code></td><td>{html.escape(str(r.get("mode","UNKNOWN")),quote=True)}</td><td><b>{html.escape(str(r.get("status","UNKNOWN")),quote=True)}</b></td><td>{html.escape(str(r.get("overall_confidence","UNKNOWN")),quote=True)}</td><td>{html.escape(str(r.get("scenario_id","UNKNOWN")),quote=True)}</td></tr>' for r in runs[:15]) or '<tr><td colspan="5">UNKNOWN — aucun run</td></tr>'
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>ACME AioOps</title><style>
body{{margin:0;background:#07111d;color:#e9f2f8;font:14px system-ui,Segoe UI,sans-serif}}header{{position:sticky;top:0;background:#0b1c2b;border-bottom:1px solid #25445a;padding:16px 28px;display:flex;justify-content:space-between;z-index:2}}main{{max-width:1500px;margin:auto;padding:26px}}h1{{font-size:34px;margin:0 0 6px}}h2{{margin-top:30px}}.muted{{color:#8fa7b8}}.grid{{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}}.card{{background:#0d2031;border:1px solid #23445b;border-radius:14px;padding:15px;min-height:78px}}.card span{{display:block;color:#9eb5c5;font-size:12px}}.card strong{{display:block;font-size:30px;margin-top:9px}}.two{{display:grid;grid-template-columns:2fr 1fr;gap:16px}}.panel{{background:#0c1d2d;border:1px solid #23445b;border-radius:14px;padding:18px;margin-top:16px}}table{{width:100%;border-collapse:collapse}}th,td{{padding:10px;border-bottom:1px solid #1d394e;text-align:left}}button{{border:0;border-radius:9px;padding:11px 15px;background:#2188c7;color:#fff;cursor:pointer;margin-right:8px}}button.secondary{{background:#18384e}}textarea{{width:100%;min-height:80px;background:#07131f;color:#fff;border:1px solid #2a4b61;border-radius:9px;padding:10px;box-sizing:border-box}}pre{{white-space:pre-wrap}}code{{color:#b8d8eb}}a{{color:#8fd0ff}}nav a{{margin-left:8px}}@media(max-width:1100px){{.grid{{grid-template-columns:repeat(3,1fr)}}.two{{grid-template-columns:1fr}}}}@media(max-width:650px){{.grid{{grid-template-columns:repeat(2,1fr)}}}}
</style></head><body><header><b>ACME AioOps 2.0</b><nav><a href="#runs">Runs</a> · <a href="#twin">Twin</a> · <a href="/demo/acme-impact">ACME Impact (simulation)</a> · <a href="#copilot">Copilot</a> · <a href="#noc">NOC</a> · <a href="#integrations">Intégrations</a></nav></header><main><h1>Operations Command Center</h1><div class="muted">Synthetic/demo data is explicitly labelled. Unsupported claims remain UNKNOWN.</div><p class="muted">Read models (non attestés) : {read_model_status}</p><div class="grid" style="margin-top:20px">{cards_html}</div><div class="panel"><label for="demo-token">Jeton opérateur DEMO (usage unique, non conservé)</label><input id="demo-token" type="password" autocomplete="off" style="margin:8px;background:#07131f;color:#fff;border:1px solid #2a4b61;padding:10px"><button onclick="demo()">Launch Golden DEMO</button><button class="secondary" onclick="location.reload()">Refresh</button><span id="demo" class="muted"></span></div><div class="two"><section class="panel" id="runs"><h2>Canonical Runs</h2><table><tr><th>Run</th><th>Mode</th><th>Status</th><th>Confidence</th><th>Scenario</th></tr>{rows}</table></section><section class="panel" id="twin"><h2>Digital Twin</h2><pre>{html.escape(json.dumps(t,indent=2,default=str))}</pre></section></div><section class="panel" id="copilot"><h2>AI Copilot</h2><textarea id="q" placeholder="Ex: Pourquoi le service Payment est-il à risque ? Quelles preuves avons-nous ?"></textarea><button onclick="ask()" style="margin-top:10px">Ask Copilot</button><pre id="a" class="muted"></pre></section><section class="panel" id="noc"><h2>NOC — Checkmk / Thruk</h2><p class="muted">Source runtime : UNKNOWN tant qu'aucun fournisseur de read-model signé n'est configuré et vérifié. Le flux de corrélation Incident/Run reste en lecture seule ; aucune preuve LIVE n'est déduite de cette page.</p><p>Contrat API : <code>GET /api/noc/runtime-state</code> (jeton opérateur obligatoire, HMAC SHA-256 et contrôle de fraîcheur). Les liens Thruk et Grafana configurés figurent dans les intégrations ci-dessous.</p><p><code>GET /api/noc/correlation</code> : rapprochement signé NOC / Run canonique, lecture seule et non attesté.</p><label for="noc-token">Jeton opérateur NOC (non enregistré)</label><input id="noc-token" type="password" autocomplete="off" style="margin:8px;background:#07131f;color:#fff;border:1px solid #2a4b61;padding:10px"><button onclick="correlateNoc()">Lire la corrélation</button><pre id="noc-result" class="muted">UNKNOWN — aucune corrélation vérifiée</pre><p><b>RAG DEMO — fiches synthétiques de PR #36</b> : citations de référence uniquement, ni observation Checkmk, ni inférence IA, ni procédure LIVE.</p><label for="noc-asset">Équipement fictif</label><input id="noc-asset" value="brocade-fc01" autocomplete="off" style="margin:8px;background:#07131f;color:#fff;border:1px solid #2a4b61;padding:10px"><button onclick="demoRag()">Lire fiches RAG DEMO</button><pre id="noc-rag-result" class="muted">UNKNOWN — aucune fiche sélectionnée</pre></section>{integration_html}</main><script>async function demo(){{let el=document.getElementById('demo-token');let token=el.value;el.value='';let out=document.getElementById('demo');if(!token){{out.textContent='UNKNOWN — jeton opérateur requis';return}}try{{let r=await fetch('/api/demo',{{method:'POST',headers:{{Authorization:'Bearer '+token}},cache:'no-store',redirect:'error'}});out.textContent=r.ok?'DEMO_CREATED_UNVERIFIED':'UNKNOWN — commande refusée ('+r.status+')';if(r.ok)setTimeout(()=>location.reload(),1500)}}catch(e){{out.textContent='UNKNOWN — service indisponible'}}}}async function ask(){{let q=document.getElementById('q').value;let r=await fetch('/api/copilot',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{question:q}})}});document.getElementById('a').textContent=JSON.stringify(await r.json(),null,2)}}async function correlateNoc(){{let el=document.getElementById('noc-token');let token=el.value;el.value='';let out=document.getElementById('noc-result');out.textContent='UNKNOWN — lecture en cours';if(!token){{out.textContent='UNKNOWN — jeton opérateur requis';return}}try{{let r=await fetch('/api/noc/correlation',{{headers:{{Authorization:'Bearer '+token}},cache:'no-store',redirect:'error'}});let data=await r.json();out.textContent=r.ok?JSON.stringify(data,null,2):'UNKNOWN — '+String(data.detail||'source indisponible')}}catch(e){{out.textContent='UNKNOWN — service indisponible'}}}}
async function demoRag(){{let el=document.getElementById('noc-token');let token=el.value;el.value='';let out=document.getElementById('noc-rag-result');let asset=document.getElementById('noc-asset').value;out.textContent='UNKNOWN — lecture en cours';if(!token){{out.textContent='UNKNOWN — jeton opérateur requis';return}}try{{let r=await fetch('/api/noc/demo-rag?asset='+encodeURIComponent(asset),{{headers:{{Authorization:'Bearer '+token}},cache:'no-store',redirect:'error'}});let data=await r.json();out.textContent=r.ok?JSON.stringify(data,null,2):'UNKNOWN — '+String(data.detail||'catalogue indisponible')}}catch(e){{out.textContent='UNKNOWN — catalogue indisponible'}}}}
</script></body></html>'''
